  <link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/4.0.0/css/bootstrap.min.css">
  <style>
    .th-sort {
      cursor: pointer;
      user-select: none;
    }
    .th-sort::after {
      content: ' ⇅';
      font-size: 0.8em;
      color: #ccc;
    }
    .th-sort:hover::after {
      color: #000;
    }
  </style>
</head>
<body>
  <table class="table table-bordered table-hover">
    <thead>
      <tr>
        <th id="name" class="th-sort">Name</th>
        <th id="age" class="th-sort">Age</th>
      </tr>
    </thead>
    <tbody>
      <tr>
        <td>Bob</td>
        <td>24</td>
      </tr>
      <tr>
        <td>Jack</td>
        <td>31</td>
      </tr>
      <tr>
        <td>Dave</td>
        <td>19</td>
      </tr>
    </tbody>
  </table>

  <script>
    // Get all table headers
    const headers = document.querySelectorAll('.th-sort');

    headers.forEach(header => {
      header.addEventListener('click', function() {
        const table = this.closest('table');
        const rows = Array.from(table.querySelectorAll('tbody tr'));
        const index = Array.from(this.parentNode.children).indexOf(this);
        const type = this.id === 'age' ? 'number' : 'string';

        // Toggle sort direction
        const sortDirection = table.getAttribute('data-sort-direction') === 'asc' ? 'desc' : 'asc';
        table.setAttribute('data-sort-direction', sortDirection);

        // Sort rows based on the clicked header
        rows.sort((a, b) => {
          const aValue = a.children[index].innerText.trim();
          const bValue = b.children[index].innerText.trim();

          if (type === 'number') {
            return sortDirection === 'asc' ? aValue - bValue : bValue - aValue;
          } else {
            return sortDirection === 'asc' ? aValue.localeCompare(bValue) : bValue.localeCompare(aValue);
          }
        });

        // Append sorted rows back to the table body
        const tbody = table.querySelector('tbody');
        tbody.innerHTML = '';
        rows.forEach(row => tbody.appendChild(row));
      });
    });
  </script>
</body>
</html>
```

